// =========================================================
// CONFIGURAÇÕES GERAIS — EDITE AQUI PARA TESTES
// =========================================================

// MODO_TESTE = true  -> NENHUM e-mail vai para alunos/formadores;
//                       todas as mensagens são redirecionadas para EMAIL_TESTE
//                       (o assunto mostra quem seria o destinatário real).
// MODO_TESTE = false -> envio real para os destinatários.
const MODO_TESTE = true;

// E-mail que recebe as mensagens quando MODO_TESTE = true
const EMAIL_TESTE = 'prof.flavio.spina@gmail.com';

// TESTE_USAR_ALIAS = true -> no MODO_TESTE cada mensagem vai para um alias único da
// caixa de teste (ex.: nome+cecape-003@gmail.com), que o Gmail entrega na mesma
// caixa. Evita que dezenas de mensagens parecidas para o MESMO endereço sejam
// tratadas como envio em massa (spam/abas) e permite conferir uma a uma.
// Funciona em Gmail e Google Workspace. Para outros provedores, use false.
const TESTE_USAR_ALIAS = true;

// DIAS_A_FRENTE: quantos dias após a data ATUAL devem ser consultados.
//   1 = dia seguinte (padrão de produção)
//   2 = daqui a dois dias, e assim por diante
//   0 = o próprio dia de hoje (útil para testes)
// A regra de fim de semana continua valendo: se a data-alvo cair num sábado,
// a segunda-feira seguinte também entra como data-alvo.
const DIAS_A_FRENTE = 0;

// E-mail da TI: recebe o aviso de divergência de nome e o relatório resumido de cada execução
const EMAIL_TI = 'ti.cecape@scseduca.com.br';

// Aba e intervalo do diário com os encontros: B = data, D = horário, F = local (a partir da linha 21).
// É a PRIMEIRA fonte de data/horário/local. Se não houver datas ali, usa a forma antiga
// (datas na linha 2 da aba FREQUÊNCIA a partir de L2; horário/local na planilha da agenda).
const ABA_ID_DIARIO = 'ID';
const RANGE_ID_DIARIO = 'B21:F';

// Demais intervalos lidos do diário, na MESMA chamada (values:batchGet) da aba ID
const RANGE_L2_DIARIO = 'FREQUÊNCIA!L2:2';     // datas dos encontros (forma antiga)
const RANGE_ALUNOS_DIARIO = 'FREQUÊNCIA!C3:D'; // alunos: C = nome, D = e-mail

// Pasta do Google Drive onde estão os diários (AAAA MM DD NOME DO CURSO DIÁRIO QR FORMAÇÃO)
const PASTA_DIARIOS_ID = '1-qF8Yh0oIXE8VJwypPjFkcjET1YCVmya';

// Planilha da agenda mensal (dados dos cursos e dos formadores)
const AGENDA_SHEET_ID = '11_isrdRYiew08xo7rZyBqx1YkvyfR7IRmrHui37x768';

// Data sentinela: ao encontrá-la na linha 2 da aba FREQUÊNCIA, para de percorrer a linha
const DATA_SENTINELA = '01/01/2026';

return [{
  json: {
    MODO_TESTE,
    EMAIL_TESTE,
    TESTE_USAR_ALIAS,
    DIAS_A_FRENTE,
    EMAIL_TI,
    ABA_ID_DIARIO,
    RANGE_ID_DIARIO,
    RANGE_L2_DIARIO,
    RANGE_ALUNOS_DIARIO,
    PASTA_DIARIOS_ID,
    AGENDA_SHEET_ID,
    DATA_SENTINELA
  }
}];

const cfg = $('Config - Variáveis').first().json;
const tz = 'America/Sao_Paulo';

function pad(v) {
  return String(v).padStart(2, '0');
}

const dias = Number(cfg.DIAS_A_FRENTE);
if (!Number.isFinite(dias) || dias < 0) {
  throw new Error('DIAS_A_FRENTE inválido: use um número inteiro >= 0 (1 = dia seguinte).');
}

const now = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
const target = new Date(now);
target.setDate(target.getDate() + Math.trunc(dias));

function buildDateMeta(date, label) {
  const yyyy = date.getFullYear();
  const mm = pad(date.getMonth() + 1);
  const dd = pad(date.getDate());
  return {
    label,
    yyyy,
    mm,
    dd,
    target_day: dd,
    target_ymd: `${yyyy}-${mm}-${dd}`,
    target_ddmmyyyy: `${dd}/${mm}/${yyyy}`,
    weekday: date.toLocaleDateString('pt-BR', { timeZone: tz, weekday: 'long' })
  };
}

const targets = [buildDateMeta(target, 'data_alvo')];

// Regra de fim de semana: se a data-alvo for sábado, inclui também a segunda-feira.
if (target.getDay() === 6) {
  const monday = new Date(target);
  monday.setDate(monday.getDate() + 2);
  targets.push(buildDateMeta(monday, 'segunda_antecipada'));
}

const target_days = [...new Set(targets.map(t => t.target_day))];
const target_ymds = [...new Set(targets.map(t => t.target_ymd))];
const target_ddmmyyyys = [...new Set(targets.map(t => t.target_ddmmyyyy))];
const month_tabs = [...new Set(targets.map(t => {
  const m = new Date(`${t.target_ymd}T12:00:00`);
  const monthName = m.toLocaleDateString('pt-BR', { timeZone: tz, month: 'long' });
  return monthName.charAt(0).toUpperCase() + monthName.slice(1);
}))];

return [{
  json: {
    modo_teste: cfg.MODO_TESTE,
    dias_a_frente: Math.trunc(dias),
    hoje: `${pad(now.getDate())}/${pad(now.getMonth() + 1)}/${now.getFullYear()}`,
    target_day: target_days[0],
    target_ymd: target_ymds[0],
    target_ddmmyyyy: target_ddmmyyyys[0],
    month_tab: month_tabs[0],
    target_days,
    target_ymds,
    target_ddmmyyyys,
    month_tabs,
    targets,
    includes_monday_advance: targets.some(t => t.label === 'segunda_antecipada')
  }
}];

// =========================================================
// Identifica as LINHAS EM VERMELHO (fundo ou texto) em cada aba
// da planilha da agenda, para que "Code - Agenda Dia Seguinte"
// as MARQUE (_linha_vermelha = true). Os dados dessas linhas
// (formadores, etapas, formato, Google Sala de Aula) continuam
// sendo usados — o envio é guiado pelo diário.
//
// Entrada: resposta de spreadsheets.get com includeGridData=true
// (uma entrada em "sheets" por aba do mês consultada).
// Saída: UM item { _linhasVermelhas: { 'ABA': [nº da linha, ...] } }
// Em caso de erro de leitura, devolve mapa vazio (nenhuma linha é
// ignorada) para não interromper o envio dos e-mails.
// =========================================================

function num(v) {
  return typeof v === 'number' && Number.isFinite(v) ? v : 0;
}

// Converte uma cor da API (campos zerados são OMITIDOS pelo Google) em {r,g,b,a}
function rgb(color) {
  if (!color || typeof color !== 'object') return null;
  return {
    r: num(color.red),
    g: num(color.green),
    b: num(color.blue),
    a: color.alpha === undefined ? 1 : num(color.alpha)
  };
}

// "Vermelho": canal R dominante, G e B baixos e parecidos entre si.
// Cobre toda a paleta de vermelhos do Google Sheets (vermelho, vermelho
// escuro 1/2/3, vermelho claro 1/2/3) e exclui laranja, rosa/magenta,
// marrom, amarelo, cinza e branco.
function isRed(c) {
  if (!c || c.a === 0) return false;
  const maxGB = Math.max(c.g, c.b);
  return c.r >= 0.35 && (c.r - maxGB) >= 0.15 && Math.abs(c.g - c.b) <= 0.1;
}

function cellColors(cell) {
  const f = (cell && cell.effectiveFormat) || {};
  const bg = rgb(f.backgroundColor) || rgb(f.backgroundColorStyle && f.backgroundColorStyle.rgbColor);
  const tf = f.textFormat || {};
  const fg = rgb(tf.foregroundColor) || rgb(tf.foregroundColorStyle && tf.foregroundColorStyle.rgbColor);
  return { bg: isRed(bg), fg: isRed(fg) };
}

function normHeader(s) {
  return String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toUpperCase()
    .trim();
}

const resp = ($input.first() && $input.first().json) || {};

let erro = '';
if (resp.error) {
  erro = typeof resp.error === 'string' ? resp.error : (resp.error.message || 'Erro ao ler a formatação da agenda');
}

const linhasVermelhas = {};
const detalhes = {};

for (const sheet of (Array.isArray(resp.sheets) ? resp.sheets : [])) {
  const title = String(((sheet || {}).properties || {}).title || '').toUpperCase();
  if (!title) continue;

  const vermelhas = [];
  const amostra = [];

  for (const block of (Array.isArray(sheet.data) ? sheet.data : [])) {
    const startRow = num(block.startRow);
    const rowData = Array.isArray(block.rowData) ? block.rowData : [];

    // Cabeçalho (linha 1): localiza a coluna TÍTULO
    let colTitulo = -1;
    if (startRow === 0 && rowData[0] && Array.isArray(rowData[0].values)) {
      rowData[0].values.forEach((c, i) => {
        if (normHeader(c && c.formattedValue) === 'TITULO') colTitulo = i;
      });
    }

    rowData.forEach((r, i) => {
      const rowNumber = startRow + i + 1; // nº da linha na planilha (1 = cabeçalho)
      if (rowNumber === 1) return;

      const cells = (r && Array.isArray(r.values)) ? r.values : [];
      let preenchidas = 0;
      let preenchidasVermelhas = 0;
      let tituloVermelho = false;

      cells.forEach((c, ci) => {
        const temValor = !!(c && c.formattedValue !== undefined && String(c.formattedValue).trim() !== '');
        if (!temValor) return;
        const { bg, fg } = cellColors(c);
        preenchidas++;
        if (bg || fg) preenchidasVermelhas++;
        if (ci === colTitulo && (bg || fg)) tituloVermelho = true;
      });

      if (!preenchidas) return;

      // Linha vermelha = célula TÍTULO vermelha OU maioria das células preenchidas vermelhas
      if (tituloVermelho || preenchidasVermelhas * 2 >= preenchidas) {
        vermelhas.push(rowNumber);
        if (amostra.length < 20) {
          const t = colTitulo >= 0 && cells[colTitulo] ? cells[colTitulo].formattedValue : '';
          amostra.push(`${rowNumber}: ${t || ''}`.trim());
        }
      }
    });
  }

  linhasVermelhas[title] = vermelhas;
  detalhes[title] = amostra;
}

return [{
  json: {
    _linhasVermelhas: linhasVermelhas,
    _linhasVermelhasTotal: Object.values(linhasVermelhas).reduce((acc, v) => acc + v.length, 0),
    _linhasVermelhasAmostra: detalhes,
    _erroFormatacao: erro
  }
}];

const prep = $('Preparar Data Alvo').first().json;

function pad(v) {
  return String(v).padStart(2, '0');
}

function normalizeDateValue(raw) {
  if (raw === null || raw === undefined || raw === '') return null;

  if (typeof raw === 'number') {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const date = new Date(excelEpoch.getTime() + raw * 86400000);
    return {
      ymd: `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`,
      day: pad(date.getUTCDate())
    };
  }

  const str = String(raw).trim();
  if (!str) return null;

  const br = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (br) {
    const [, d, m, y] = br;
    return { ymd: `${y}-${pad(m)}-${pad(d)}`, day: pad(d) };
  }

  const iso = str.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) {
    const [, y, m, d] = iso;
    return { ymd: `${y}-${m}-${d}`, day: d };
  }

  const onlyDay = str.match(/^\d{1,2}$/);
  if (onlyDay) {
    return { ymd: null, day: pad(str) };
  }

  return null;
}

const targetDays = new Set((prep.target_days || []).map(v => String(v).padStart(2, '0')));
const targetYmds = new Set(prep.target_ymds || []);

const seen = new Map(); // chave -> índice em `agenda`, para a duplicada não vermelha substituir a vermelha
const agenda = [];

// ----- linhas em VERMELHO na planilha da agenda: MANTER, apenas marcar -----
// A linha vermelha indica cancelamento/remarcação na agenda, mas os dados dela
// (FORMADORES, ETAPAS, FORMATO, GOOGLE SALA DE AULA) continuam valendo para os
// cursos cujo envio é guiado pelo diário. A linha entra na agenda com
// _linha_vermelha = true; em caso de empate de nome, "Montar Fila" prefere a
// linha NÃO vermelha (a agenda é ordenada com as não vermelhas primeiro).
// Mapa { 'ABA': [nº da linha, ...] } calculado em "Code - Linhas Vermelhas Agenda".
let linhasVermelhas = {};
try {
  linhasVermelhas = $('Code - Linhas Vermelhas Agenda').first().json._linhasVermelhas || {};
} catch (e) {
  linhasVermelhas = {};
}
const abas = (prep.month_tabs && prep.month_tabs.length ? prep.month_tabs : [prep.month_tab]).map(t => String(t).toUpperCase());
const abaMes1 = abas[0];
const abaMes2 = abas[1] || abas[0];
const vermelhasMes1 = new Set((linhasVermelhas[abaMes1] || []).map(Number));
const vermelhasMes2 = new Set((linhasVermelhas[abaMes2] || []).map(Number));

// O Merge (append) entrega primeiro as linhas do Mês 1 e depois as do Mês 2.
let qtdMes1 = items.length;
try {
  qtdMes1 = $('Sheets - Agenda Mês 1').all().length;
} catch (e) {
  qtdMes1 = items.length;
}

let marcadasVermelhas = 0;

for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const row = item.json;

  const doMes1 = idx < qtdMes1;
  const numeroLinha = Number(row.row_number) || (doMes1 ? idx + 2 : idx - qtdMes1 + 2);
  const linhaVermelha = (doMes1 ? vermelhasMes1 : vermelhasMes2).has(numeroLinha);
  if (linhaVermelha) marcadasVermelhas++;

  const parsed = normalizeDateValue(row['DATA'] ?? row['Data'] ?? row['data']);
  if (!parsed) continue;

  const match = (parsed.ymd && targetYmds.has(parsed.ymd)) || targetDays.has(parsed.day);
  if (!match) continue;

  const key = [row['DATA'] ?? '', row['TÍTULO'] ?? '', row['INÍCIO'] ?? row['INICIO'] ?? ''].join('|');
  const nova = { ...row, _data_ymd: parsed.ymd || '', _data_dia: parsed.day, _linha_vermelha: linhaVermelha };
  const idxExistente = seen.get(key);
  if (idxExistente !== undefined) {
    // Linha duplicada: mantém a versão NÃO vermelha
    if (agenda[idxExistente]._linha_vermelha && !linhaVermelha) agenda[idxExistente] = nova;
    continue;
  }
  seen.set(key, agenda.length);
  agenda.push(nova);
}

// Linhas NÃO vermelhas primeiro: no "Montar Fila" a busca usa comparação
// estrita (score > melhor), então, em empate de nome, a linha não vermelha vence.
agenda.sort((a, b) => (a._linha_vermelha ? 1 : 0) - (b._linha_vermelha ? 1 : 0));

// Empacota tudo em UM item para o fluxo continuar mesmo sem cursos na agenda.
return [{ json: { _agenda: agenda, _agendaCount: agenda.length, _linhasVermelhasMarcadas: marcadasVermelhas } }];

function normalize(s = '') {
  return String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\.(xlsx|xls|csv)$/i, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const seen = new Set();
const out = [];

for (const item of items) {
  const id = String(item.json.id || '').trim();
  const name = String(item.json.name || '').trim();
  if (!id || !name || seen.has(id)) continue;
  seen.add(id);

  // Apenas arquivos "... DIÁRIO QR FORMAÇÃO"
  const norm = normalize(name);
  if (!norm.includes('diario qr formacao')) continue;

  // Nome do curso = nome do arquivo sem o prefixo "AAAA MM DD" e sem o sufixo "DIÁRIO QR FORMAÇÃO"
  const curso_nome = name
    .replace(/^\s*\d{4}[\s._-]+\d{1,2}[\s._-]+\d{1,2}[\s._-]*/, '')
    .replace(/[-–—]?\s*di[aá]rio\s+qr\s+forma[cç][aã]o.*$/i, '')
    .replace(/\.(xlsx|xls|csv)$/i, '')
    .trim() || name;

  out.push({
    json: {
      spreadsheetId: id,
      spreadsheetName: name,
      curso_nome,
      course_key: normalize(curso_nome)
    }
  });
}

out.sort((a, b) => a.json.spreadsheetName.localeCompare(b.json.spreadsheetName, 'pt-BR'));

return out;

const prep = $('Preparar Data Alvo').first().json;
const cfg = $('Config - Variáveis').first().json;

// Os diários originais, na MESMA ordem em que entraram no nó HTTP
// (o nó HTTP devolve exatamente um item de resposta por item de entrada).
const diarios = $('Code - Preparar Diários').all().map(i => i.json);

function pad(v) {
  return String(v).padStart(2, '0');
}

function toDate(raw) {
  if (raw === null || raw === undefined || raw === '') return null;

  if (typeof raw === 'number') {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const d = new Date(excelEpoch.getTime() + raw * 86400000);
    return {
      ddmmyyyy: `${pad(d.getUTCDate())}/${pad(d.getUTCMonth() + 1)}/${d.getUTCFullYear()}`,
      ddmm: `${pad(d.getUTCDate())}/${pad(d.getUTCMonth() + 1)}`
    };
  }

  const str = String(raw).trim();
  if (!str) return null;

  let m = str.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return { ddmmyyyy: `${pad(m[1])}/${pad(m[2])}/${m[3]}`, ddmm: `${pad(m[1])}/${pad(m[2])}` };

  m = str.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) return { ddmmyyyy: `${m[3]}/${m[2]}/${m[1]}`, ddmm: `${m[3]}/${m[2]}` };

  m = str.match(/^(\d{1,2})\/(\d{1,2})$/);
  if (m) return { ddmmyyyy: '', ddmm: `${pad(m[1])}/${pad(m[2])}` };

  return null;
}

const sentinela = toDate(cfg.DATA_SENTINELA) || { ddmmyyyy: '01/01/2026', ddmm: '01/01' };
const targetsFull = new Set(prep.target_ddmmyyyys || []);
const targetsDDMM = new Set((prep.target_ddmmyyyys || []).map(v => v.slice(0, 5)));

// ---------------------------------------------------------------
// LEITURA DO DIÁRIO EM UMA ÚNICA CHAMADA (values:batchGet), 3 intervalos:
//   [0] FREQUÊNCIA!L2:2  -> datas dos encontros (forma antiga)
//   [1] ID!B21:F         -> encontros: B = data, D = horário, F = local
//   [2] FREQUÊNCIA!C3:D  -> alunos: C = nome, D = e-mail
// Uma chamada por diário (em vez de três) para não estourar a cota de
// leituras da API do Sheets (60/min por usuário), que era a causa de
// listas de alunos voltando vazias.
//
// ORDEM DE CONSULTA DA DATA / HORÁRIO / LOCAL:
//   1) Aba ID: se alguma linha tiver a data-alvo -> curso do dia, com horário/local da linha.
//   2) Se a aba ID NÃO tiver nenhuma data -> linha 2 da FREQUÊNCIA a partir de L2 (até a sentinela).
//   Horário/local vazios na aba ID são completados pela planilha da agenda em "Montar Fila".
// `items` = respostas do batchGet (um item por diário, na mesma ordem de "Code - Preparar Diários").
// ---------------------------------------------------------------
function str(v) {
  return v === null || v === undefined ? '' : String(v).replace(/\s+/g, ' ').trim();
}

// Horário pode vir como texto ("das 19h às 21h") ou como fração de dia (hora do Sheets)
function fmtHorario(raw) {
  if (raw === null || raw === undefined || raw === '') return '';
  if (typeof raw === 'number') {
    if (raw > 0 && raw < 1) {
      const total = Math.round(raw * 24 * 60);
      const h = Math.floor(total / 60);
      const m = total % 60;
      return m ? `${h}h${pad(m)}` : `${h}h`;
    }
    return String(raw);
  }
  return str(raw);
}

function ehSentinela(d) {
  return (d.ddmmyyyy && sentinela.ddmmyyyy && d.ddmmyyyy === sentinela.ddmmyyyy) ||
    (!d.ddmmyyyy && d.ddmm === sentinela.ddmm);
}

function ehAlvo(d) {
  return (d.ddmmyyyy && targetsFull.has(d.ddmmyyyy)) ||
    (!d.ddmmyyyy && targetsDDMM.has(d.ddmm));
}

function rotuloAlvo(d) {
  return d.ddmmyyyy || [...targetsFull].find(t => t.startsWith(d.ddmm)) || d.ddmm;
}

function msgErro(resp) {
  if (!resp || !resp.error) return '';
  if (typeof resp.error === 'string') return resp.error;
  return resp.error.message || resp.error.description || JSON.stringify(resp.error).slice(0, 200);
}

// Localiza um intervalo do batchGet pelo nome da aba/intervalo (ou pela posição)
function faixa(resp, idxFaixa, textoFaixa) {
  const vr = Array.isArray(resp.valueRanges) ? resp.valueRanges : [];
  const alvo = String(textoFaixa || '').toLowerCase().replace(/'/g, '');
  const porNome = vr.find(v => String(v.range || '').toLowerCase().replace(/'/g, '').startsWith(alvo.split('!')[0]) &&
    String(v.range || '').toLowerCase().includes(alvo.split('!')[1] ? alvo.split('!')[1].split(':')[0] : ''));
  const v = porNome || vr[idxFaixa] || {};
  return Array.isArray(v.values) ? v.values : [];
}

const out = [];
const semAula = [];

items.forEach((item, idx) => {
  const resp = item.json || {};
  const diario = diarios[idx] || {};
  const erroLeitura = msgErro(resp);

  const rangeL2 = String(cfg.RANGE_L2_DIARIO || 'FREQUÊNCIA!L2:2');
  const rangeId = String(cfg.ABA_ID_DIARIO || 'ID') + '!' + String(cfg.RANGE_ID_DIARIO || 'B21:F');
  const rangeAlunos = String(cfg.RANGE_ALUNOS_DIARIO || 'FREQUÊNCIA!C3:D');

  const linhasL2 = faixa(resp, 0, rangeL2);
  const linhasId = faixa(resp, 1, rangeId);
  const linhasAlunos = faixa(resp, 2, rangeAlunos);

  // ----- 1) aba ID (B21:F): B = data (0), D = horário (2), F = local (4) -----
  const encontros = [];
  for (const r of linhasId) {
    if (!Array.isArray(r)) continue;
    const d = toDate(r[0]);
    if (!d || ehSentinela(d)) continue;
    encontros.push({ d, horario: fmtHorario(r[2]), local: str(r[4]) });
  }

  let matched = '';
  let fonte = '';
  let horarioDiario = '';
  let localDiario = '';

  if (encontros.length) {
    const hit = encontros.find(e => ehAlvo(e.d));
    if (hit) {
      matched = rotuloAlvo(hit.d);
      fonte = 'DIARIO_ID';
      horarioDiario = hit.horario;
      localDiario = hit.local;
    } else {
      fonte = 'DIARIO_ID_SEM_AULA_NA_DATA';
    }
  } else {
    // ----- 2) forma antiga: linha 2 da FREQUÊNCIA a partir de L2; para na sentinela -----
    const row = Array.isArray(linhasL2[0]) ? linhasL2[0] : [];
    for (const cell of row) {
      const d = toDate(cell);
      if (!d) continue;
      if (ehSentinela(d)) break;
      if (ehAlvo(d)) {
        matched = rotuloAlvo(d);
        break;
      }
    }
    fonte = matched ? 'FREQUENCIA_L2' : (erroLeitura ? 'ERRO_LEITURA' : 'FREQUENCIA_L2_SEM_AULA_NA_DATA');
  }

  if (matched) {
    out.push({
      json: {
        spreadsheetId: diario.spreadsheetId,
        spreadsheetName: diario.spreadsheetName,
        curso_nome: diario.curso_nome,
        course_key: diario.course_key,
        TEM_CURSO: true,
        DATA_MATCH: matched,
        FONTE_DATA: fonte,
        HORARIO_DIARIO: horarioDiario,
        LOCAL_DIARIO: localDiario,
        ENCONTROS_ID: encontros.length,
        ALUNOS_ROWS: linhasAlunos,
        ALUNOS_LINHAS_LIDAS: linhasAlunos.length,
        ERRO_LEITURA: erroLeitura
      }
    });
  } else {
    semAula.push({ arquivo: diario.spreadsheetName, fonte, encontros_id: encontros.length, erro: erroLeitura });
  }
});

if (!out.length) {
  return [{
    json: {
      TEM_CURSO: false,
      _motivo: 'Nenhum diário com aula na(s) data(s)-alvo: ' + (prep.target_ddmmyyyys || []).join(', '),
      _diarios_verificados: semAula
    }
  }];
}

return out;

// Monta UMA fila ordenada de envios:
//   alunos do curso 1 -> formadores do curso 1 -> alunos do curso 2 -> ...
// Assim o envio usa um ÚNICO loop, evitando o bug conhecido do n8n com
// loops aninhados de Split In Batches (github.com/n8n-io/n8n/issues/23670).

const agenda = ($('Code - Agenda Dia Seguinte').first().json._agenda) || [];

// Cursos com aula na data-alvo, na MESMA ordem em que entraram no nó HTTP.
const cursos = $('Code - Verificar Datas').all().map(i => i.json);

function normalize(s = '') {
  return String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\.(xlsx|xls|csv)$/i, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function scoreMatch(fileKey, agendaKey) {
  if (!fileKey || !agendaKey) return 0;
  if (fileKey === agendaKey) return 1000;
  if (fileKey.includes(agendaKey) || agendaKey.includes(fileKey)) return 800;

  const fileTokens = new Set(fileKey.split(' ').filter(Boolean));
  const agendaTokens = new Set(agendaKey.split(' ').filter(Boolean));

  let common = 0;
  for (const t of fileTokens) {
    if (agendaTokens.has(t)) common++;
  }
  if (!common) return 0;
  return common * 10 - Math.abs(fileTokens.size - agendaTokens.size);
}

function formadoresDisplay(raw) {
  return String(raw || '')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map(l => l
      .replace(/^[-–•\s]+/, '')
      .replace(/\s*[-–]\s*[^\s@]+@[^\s@]+\.[^\s@]+\s*$/i, '')
      .replace(/<[^>]*>/g, '')
      .trim())
    .filter(Boolean)
    .filter(l => !/^(formadores|professores)( externos)?:?$/i.test(l))
    .join(', ');
}

function normalizeRawText(text = '') {
  return String(text || '')
    .replace(/\\r\\n/g, '\n')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\n')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function splitLines(text = '') {
  return normalizeRawText(text)
    .split('\n')
    .map(v => v.trim())
    .filter(Boolean);
}

function cleanLine(value = '') {
  return String(value || '')
    .replace(/^[-–•\s]+/, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isHeaderLine(s) {
  const t = String(s || '').trim().toUpperCase();
  return [
    'FORMADORES:',
    'FORMADORES',
    'FORMADORES EXTERNOS:',
    'FORMADORES EXTERNOS',
    'PROFESSORES:',
    'PROFESSORES',
    'PROFESSORES EXTERNOS:',
    'PROFESSORES EXTERNOS'
  ].includes(t);
}

function parsePerson(rawLine) {
  const value = cleanLine(rawLine);
  if (!value || isHeaderLine(value)) return null;

  let m = value.match(/^(.*?)\s*-\s*([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})$/i);
  if (m) {
    return { nome: cleanLine(m[1]), email: m[2].trim().toLowerCase() };
  }

  m = value.match(/^(.*?)<\s*([^>]+@[^>]+)\s*>$/);
  if (m) {
    return { nome: cleanLine(m[1]) || m[2].trim(), email: m[2].trim().toLowerCase() };
  }

  m = value.match(/^([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})$/i);
  if (m) {
    return { nome: m[1].trim(), email: m[1].trim().toLowerCase() };
  }

  return null;
}

// ----- frases dinâmicas conforme a distância entre hoje e a data do curso -----
const hojeStr = $('Preparar Data Alvo').first().json.hoje; // DD/MM/AAAA

function parseBR(s) {
  const m = String(s || '').match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  return m ? new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]), 12, 0, 0) : null;
}

function capitalize(s) {
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
}

function frasesDoDia(dataBR) {
  if (!dataBR) {
    return { DIA_SEMANA: '', FRASE_ABERTURA: 'Em breve', REF_DIA: 'do curso' };
  }
  const alvo = parseBR(dataBR);
  const hoje = parseBR(hojeStr);
  const weekday = alvo ? capitalize(alvo.toLocaleDateString('pt-BR', { weekday: 'long' })) : '';
  const diff = (alvo && hoje) ? Math.round((alvo - hoje) / 86400000) : null;
  const masculino = /sábado|domingo/i.test(weekday);

  // FRASE_ABERTURA completa a frase: "... teremos um compromisso importante no CECAPE!"
  // REF_DIA completa a frase: "... a mensagem sobre o compromisso ..."
  if (diff === 0) {
    return { DIA_SEMANA: weekday, FRASE_ABERTURA: `Hoje, ${weekday},`, REF_DIA: `de hoje (${weekday})` };
  }
  if (diff === 1) {
    return { DIA_SEMANA: weekday, FRASE_ABERTURA: `Amanhã, ${weekday},`, REF_DIA: `de amanhã (${weekday})` };
  }
  if (diff !== null && diff > 1) {
    return {
      DIA_SEMANA: weekday,
      FRASE_ABERTURA: masculino
        ? `No próximo ${weekday}, dia ${dataBR},`
        : `Na próxima ${weekday}, dia ${dataBR},`,
      REF_DIA: masculino
        ? `do próximo ${weekday} (${dataBR})`
        : `da próxima ${weekday} (${dataBR})`
    };
  }
  return { DIA_SEMANA: weekday, FRASE_ABERTURA: `No dia ${dataBR},`, REF_DIA: `do dia ${dataBR}` };
}

// "das 19h às 21h" -> { inicio: '19h', fim: '21h' }; "19:00 - 21:00" -> { inicio: '19:00', fim: '21:00' }
function parseHorario(txt) {
  const t = String(txt || '').trim();
  if (!t) return null;
  const m = t.match(/(\d{1,2}(?:\s*[:h]\s*\d{2})?\s*h?)\s*(?:às|as|a|até|-|–|—)\s*(\d{1,2}(?:\s*[:h]\s*\d{2})?\s*h?)/i);
  if (m) return { inicio: m[1].replace(/\s+/g, ''), fim: m[2].replace(/\s+/g, '') };
  return { inicio: t, fim: '' };
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const fila = [];

function escapeHtml(s = '') {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

items.forEach((item, idx) => {
  // Cada item é um curso do dia (saída de "Code - Verificar Datas"), já com as linhas de alunos
  // lidas na mesma chamada do diário (ALUNOS_ROWS: C = nome, D = e-mail).
  const info = item.json || cursos[idx] || {};
  const resp = { values: Array.isArray(info.ALUNOS_ROWS) ? info.ALUNOS_ROWS : [] };
  const dm = String(info.DATA_MATCH || '');

  // ----- localizar o curso na agenda mensal (sala, horário, formadores) -----
  let curso = null;
  let bestScore = 0;

  for (const a of agenda) {
    const aKey = normalize(a['TÍTULO'] || a['TITULO'] || '');
    let score = scoreMatch(info.course_key, aKey);
    if (dm && a._data_ymd && dm === a._data_ymd.split('-').reverse().join('/')) score += 50;
    else if (dm && a._data_dia && dm.slice(0, 2) === a._data_dia) score += 20;
    if (score > bestScore) {
      bestScore = score;
      curso = a;
    }
  }

  const encontrado = !!curso && bestScore >= 10;

  // ----- horário/local: PRIMEIRO do diário (aba ID, B21:F); se vazio, da planilha da agenda -----
  const horarioDiario = String(info.HORARIO_DIARIO || '').trim();
  const localDiario = String(info.LOCAL_DIARIO || '').trim();
  const hDiario = parseHorario(horarioDiario);
  const inicioAgenda = encontrado ? String(curso['INÍCIO'] ?? curso['INICIO'] ?? '').trim() : '';
  const terminoAgenda = encontrado ? String(curso['TÉRMINO'] ?? curso['TERMINO'] ?? '').trim() : '';
  const localAgenda = encontrado ? String(curso['ESPAÇO'] ?? curso['ESPACO'] ?? '').trim() : '';
  const inicioFinal = hDiario ? hDiario.inicio : inicioAgenda;
  const terminoFinal = hDiario ? hDiario.fim : terminoAgenda;
  const horarioTexto = horarioDiario || [inicioAgenda, terminoAgenda].filter(Boolean).join(' - ');
  const formadoresRaw = encontrado ? String(curso['FORMADORES'] ?? curso['PROFESSORES'] ?? '') : '';

  const cursoInfo = {
    spreadsheetId: info.spreadsheetId,
    spreadsheetName: info.spreadsheetName,
    curso_nome: info.curso_nome,
    course_key: info.course_key,
    DATA: dm || (encontrado ? String(curso['DATA'] ?? '') : ''),
    // Nome do curso: se a linha da agenda estiver VERMELHA, usa o nome do DIÁRIO
    // (idêntico ao arquivo, sem as anotações da agenda); senão, o TÍTULO da agenda.
    'TÍTULO': encontrado && curso['TÍTULO'] && !curso._linha_vermelha ? curso['TÍTULO'] : info.curso_nome,
    'ESPAÇO': localDiario || localAgenda,
    INICIO: inicioFinal,
    TERMINO: terminoFinal,
    HORARIO_TEXTO: horarioTexto,
    FONTE_DATA: info.FONTE_DATA || '',
    FONTE_HORARIO: horarioDiario ? 'DIARIO' : 'AGENDA',
    FONTE_LOCAL: localDiario ? 'DIARIO' : 'AGENDA',
    ETAPAS: encontrado ? (curso['ETAPAS'] ?? '') : '',
    FORMATO: encontrado ? (curso['FORMATO'] ?? '') : '',
    'GOOGLE SALA DE AULA': encontrado ? (curso['GOOGLE SALA DE AULA'] ?? '') : '',
    FORMADORES: formadoresDisplay(formadoresRaw),
    CURSO_ENCONTRADO_NA_AGENDA: encontrado,
    ERRO_LEITURA_DIARIO: info.ERRO_LEITURA || '',
    ALUNOS_LINHAS_LIDAS: Number(info.ALUNOS_LINHAS_LIDAS || 0),
    SCORE_AGENDA: bestScore
  };

  Object.assign(cursoInfo, frasesDoDia(cursoInfo.DATA));

  // ----- alunos: coluna C = nome, coluna D = e-mail (a partir da linha 3) -----
  const rows = Array.isArray(resp.values) ? resp.values : [];
  const seenAlunos = new Set();
  const alunosNomes = []; // nomes dos alunos avisados (na ordem do diário), para o e-mail do formador

  for (const r of rows) {
    const nome = String((r && r[0]) || '').trim();
    const email = String((r && r[1]) || '').trim().toLowerCase();
    if (!email || !emailRegex.test(email)) continue;
    if (seenAlunos.has(email)) continue;
    seenAlunos.add(email);
    alunosNomes.push(nome || email);

    fila.push({
      json: {
        ...cursoInfo,
        TIPO_ENVIO: 'ALUNO',
        NOME: nome || email,
        EMAIL_ALUNO: email
      }
    });
  }

  // ----- lista de alunos para o e-mail do formador -----
  const alunosListaHtml = alunosNomes.length
    ? '<ol class="alunos-lista">' + alunosNomes.map(n => '<li>' + escapeHtml(n) + '</li>').join('') + '</ol>'
    : '<p class="alunos-vazio">Nenhum aluno com e-mail cadastrado no diário.</p>';

  // ----- formadores do MESMO curso, logo após os alunos -----
  const seenProf = new Set();

  for (const linha of splitLines(formadoresRaw)) {
    const p = parsePerson(linha);
    if (!p || !p.email) continue;
    if (seenProf.has(p.email)) continue;
    seenProf.add(p.email);

    fila.push({
      json: {
        ...cursoInfo,
        TIPO_ENVIO: 'FORMADOR',
        PROFESSOR_NOME: p.nome,
        PROFESSOR_EMAIL: p.email,
        HORARIO_INICIO: cursoInfo.INICIO || '',
        HORARIO_FIM: cursoInfo.TERMINO || '',
        TITULO_CURSO: cursoInfo['TÍTULO'] || info.curso_nome,
        ALUNOS_TOTAL: alunosNomes.length,
        ALUNOS_NOMES: alunosNomes,
        ALUNOS_LISTA_HTML: alunosListaHtml
      }
    });
  }
});

if (!fila.length) {
  return [{
    json: {
      TIPO_ENVIO: 'NENHUM',
      _motivo: 'Cursos com aula na data-alvo foram encontrados, mas sem alunos/formadores com e-mail válido.'
    }
  }];
}

return fila.map((f, i) => ({ json: { ...f.json, ORDEM: i + 1, TOTAL_FILA: fila.length } }));

// =========================================================
// REGRA: NOME DO ARQUIVO DO DIÁRIO x TÍTULO DA PLANILHA DA AGENDA
// ---------------------------------------------------------
// Recebe a fila montada por "Code - Montar Fila de Envios".
// DISPENSA: curso cujo diário já trouxe DATA (aba ID) + HORÁRIO + SALA
// não precisa da agenda — nenhuma conferência de nome é feita.
// Para os demais, para cada curso cujo nome NÃO confere com o TÍTULO
// da planilha da agenda:
//   - remove os envios de ALUNO e FORMADOR daquele curso;
//   - insere UM item TIPO_ENVIO = 'DIVERGENCIA', enviado para EMAIL_TI,
//     com os dados do curso, formadores e a lista dos alunos não avisados.
//
// COMO OS NOMES SÃO COMPARADOS (mesma lógica dos nós existentes):
//   • Lado do arquivo: usa o nome já "quebrado" por "Code - Preparar Diários"
//     (sem o prefixo "AAAA MM DD" e sem o sufixo "DIÁRIO QR FORMAÇÃO").
//   • Lado da planilha: remove o código de turma que antecede o título
//     ("U - ", "U1 - ", "A15 - ", "C1 - ", "U: " ...).
//   • Os dois lados passam pela mesma normalização de "Montar Fila"
//     (sem acentos, minúsculas, sem pontuação, espaços únicos).
//   • Nome CONFERE quando são iguais OU um está contido no outro — a mesma
//     regra que "Montar Fila" usa para localizar o curso na agenda.
//     Coincidência só por palavras soltas NÃO confere.
// =========================================================

let EMAIL_TI = 'ti.cecape@scseduca.com.br';
try { EMAIL_TI = ($('Config - Variáveis').first().json.EMAIL_TI || EMAIL_TI).trim(); } catch (e) { /* mantém o padrão */ }

function normalize(s = '') {
  return String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\.(xlsx|xls|csv)$/i, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Remove o código de turma do início do TÍTULO da planilha: "U - ", "U1 - ", "A15 - ", "U: "
function limpaTituloPlanilha(t = '') {
  return String(t || '')
    .replace(/\r\n?/g, '\n')
    .trim()
    .replace(/^[A-Za-z]{1,2}\s*\d{0,2}\s*[-–—:]\s*/u, '')
    .trim();
}

function chavePlanilha(t) {
  return normalize(limpaTituloPlanilha(t));
}

function nomesConferem(chaveArquivo, chavePlan) {
  if (!chaveArquivo || !chavePlan) return false;
  if (chaveArquivo === chavePlan) return true;
  // "um contido no outro" só vale para nomes com tamanho mínimo, para evitar coincidências triviais
  if (chaveArquivo.length >= 8 && chavePlan.length >= 8 &&
      (chaveArquivo.includes(chavePlan) || chavePlan.includes(chaveArquivo))) return true;

  // Tolerância a anotações que não mudam o curso: sufixos como "- FUNDAMENTAL",
  // observações como "CANCELADA PELA FORMADORA", artigo no início ("As práticas..."),
  // pequenas diferenças de pontuação. CONFEREM quando quase todas as palavras do
  // nome mais curto (>= 85%) aparecem no nome mais longo. Nomes realmente
  // diferentes compartilham poucas palavras e continuam sendo divergência.
  const tokensArquivo = chaveArquivo.split(' ').filter(Boolean);
  const tokensPlan = chavePlan.split(' ').filter(Boolean);
  const [curto, longo] = tokensArquivo.length <= tokensPlan.length
    ? [tokensArquivo, tokensPlan]
    : [tokensPlan, tokensArquivo];
  if (curto.length < 4) return false;
  const setLongo = new Set(longo);
  let presentes = 0;
  for (const t of curto) if (setLongo.has(t)) presentes++;
  return presentes / curto.length >= 0.85;
}

function escapeHtml(s = '') {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Agenda do dia (todas as linhas que casaram com a data-alvo)
let agenda = [];
try {
  agenda = ($('Code - Agenda Dia Seguinte').first().json._agenda) || [];
} catch (e) {
  agenda = [];
}
const agendaPreparada = agenda.map(a => ({
  row: a,
  titulo: String(a['TÍTULO'] ?? a['TITULO'] ?? ''),
  chave: chavePlanilha(a['TÍTULO'] ?? a['TITULO'] ?? ''),
  dataBR: a._data_ymd ? a._data_ymd.split('-').reverse().join('/') : '',
  dia: a._data_dia || ''
}));

let cfg = {};
try { cfg = $('Config - Variáveis').first().json || {}; } catch (e) { cfg = {}; }

const entrada = items.map(i => i.json);

// Item "NENHUM" (fila vazia) passa direto
if (entrada.length === 1 && entrada[0].TIPO_ENVIO === 'NENHUM') {
  return items;
}

// Agrupa por curso (spreadsheetId), preservando a ordem de chegada
const ordemCursos = [];
const porCurso = new Map();
for (const it of entrada) {
  const key = String(it.spreadsheetId || it.spreadsheetName || '');
  if (!porCurso.has(key)) {
    porCurso.set(key, []);
    ordemCursos.push(key);
  }
  porCurso.get(key).push(it);
}

const saida = [];
let divergencias = 0;

for (const key of ordemCursos) {
  const envios = porCurso.get(key);
  const base = envios[0];

  // REGRA: se o arquivo do diário já forneceu a DATA (aba ID), o HORÁRIO e a SALA,
  // a planilha da agenda (FORMAÇÕES DE APROFUNDAMENTO) não é necessária para este
  // curso — a conferência de nome é DISPENSADA e os envios seguem normalmente.
  const diarioCompleto =
    String(base.FONTE_DATA || '') === 'DIARIO_ID' &&
    String(base.FONTE_HORARIO || '') === 'DIARIO' &&
    String(base.FONTE_LOCAL || '') === 'DIARIO';

  if (diarioCompleto) {
    for (const e of envios) {
      saida.push({
        ...e,
        NOME_CONFERE: true,
        NOME_VERIFICACAO: 'DISPENSADA_DIARIO_COMPLETO',
        NOME_PLANILHA: String(e['TÍTULO'] || e.curso_nome || '').trim()
      });
    }
    continue;
  }

  const chaveArquivo = base.course_key || normalize(base.curso_nome || '');
  const dataCurso = String(base.DATA || '');

  // Procura na agenda uma linha cujo título (sem o código de turma) confere com o nome do arquivo.
  // Prioriza linhas da mesma data; se não houver, aceita qualquer linha da agenda do dia.
  const candidatas = agendaPreparada.filter(a => nomesConferem(chaveArquivo, a.chave));
  const mesmaData = candidatas.filter(a =>
    (a.dataBR && dataCurso && a.dataBR === dataCurso) ||
    (!a.dataBR && a.dia && dataCurso && dataCurso.slice(0, 2) === a.dia)
  );
  const confere = mesmaData[0] || candidatas[0] || null;
  const nomeConfere = !!confere;

  if (nomeConfere) {
    for (const e of envios) saida.push({ ...e, NOME_CONFERE: true, NOME_VERIFICACAO: 'CONFERIDA_NA_AGENDA', NOME_PLANILHA: confere.titulo.trim() });
    continue;
  }

  // ---- divergência ----
  divergencias++;
  const score = Number(base.SCORE_AGENDA) || 0;
  const encontradoForte = !!base.CURSO_ENCONTRADO_NA_AGENDA && score >= 800;
  const tituloMaisParecido = base.CURSO_ENCONTRADO_NA_AGENDA ? String(base['TÍTULO'] || '').trim() : '';

  const alunos = envios
    .filter(e => e.TIPO_ENVIO === 'ALUNO')
    .map(e => ({ nome: e.NOME || e.EMAIL_ALUNO || '', email: e.EMAIL_ALUNO || '' }));

  const listaHtml = alunos.length
    ? '<ol class="alunos-lista">' + alunos.map(a =>
        '<li>' + escapeHtml(a.nome) +
        (a.email && a.email !== a.nome ? ' <span class="aluno-email">(' + escapeHtml(a.email) + ')</span>' : '') +
        '</li>').join('') + '</ol>'
    : '<p class="alunos-vazio">Nenhum aluno com e-mail cadastrado no diário.</p>';

  // Dados do curso: só usa os dados da agenda quando a correspondência é forte.
  // Em coincidência fraca, zera para não exibir dados de OUTRO curso no aviso.
  const dados = encontradoForte ? base : {
    ...base,
    'TÍTULO': base.curso_nome || base['TÍTULO'] || '',
    'ESPAÇO': base.FONTE_LOCAL === 'DIARIO' ? (base['ESPAÇO'] || '') : '',
    INICIO: base.FONTE_HORARIO === 'DIARIO' ? (base.INICIO || '') : '',
    TERMINO: base.FONTE_HORARIO === 'DIARIO' ? (base.TERMINO || '') : '',
    HORARIO_TEXTO: base.FONTE_HORARIO === 'DIARIO' ? (base.HORARIO_TEXTO || '') : '',
    ETAPAS: '',
    FORMATO: '',
    'GOOGLE SALA DE AULA': '',
    FORMADORES: ''
  };

  const {
    NOME, EMAIL_ALUNO, PROFESSOR_NOME, PROFESSOR_EMAIL, TITULO_CURSO,
    ALUNOS_NOMES, ALUNOS_LISTA_HTML, ALUNOS_TOTAL, ORDEM, TOTAL_FILA,
    ...cursoInfo
  } = dados;

  saida.push({
    ...cursoInfo,
    TIPO_ENVIO: 'DIVERGENCIA',
    EMAIL_TI,
    NOME_CONFERE: false,
    NOME_ARQUIVO: base.curso_nome || '',
    NOME_PLANILHA: tituloMaisParecido,
    MOTIVO_DIVERGENCIA: tituloMaisParecido
      ? 'O nome do curso no arquivo do diário é diferente do TÍTULO na planilha da agenda (título mais parecido indicado abaixo).'
      : 'Não foi encontrado na planilha da agenda nenhum curso com o nome do arquivo do diário para a data-alvo.',
    HORARIO_INICIO: cursoInfo.INICIO || '',
    HORARIO_FIM: cursoInfo.TERMINO || '',
    ALUNOS_TOTAL: alunos.length,
    ALUNOS_NOMES: alunos.map(a => a.nome),
    ALUNOS_LISTA_HTML: listaHtml,
    ENVIOS_SUPRIMIDOS: envios.length
  });
}

if (!saida.length) {
  return [{ json: { TIPO_ENVIO: 'NENHUM', _motivo: 'Nenhum envio após aplicar a regra de nomes.' } }];
}

// ----- destinatários: real e do modo teste (alias único por mensagem) -----
const emailTeste = String(cfg.EMAIL_TESTE || '').trim();
const usarAlias = cfg.TESTE_USAR_ALIAS !== false && /^[^@+\s]+@[^@\s]+$/.test(emailTeste);
const [tLocal, tDominio] = emailTeste.split('@');
const total = saida.length;
const pad = String(total).length < 3 ? 3 : String(total).length;

function emailReal(j) {
  if (j.TIPO_ENVIO === 'ALUNO') return j.EMAIL_ALUNO || '';
  if (j.TIPO_ENVIO === 'FORMADOR') return j.PROFESSOR_EMAIL || '';
  if (j.TIPO_ENVIO === 'DIVERGENCIA') return j.EMAIL_TI || EMAIL_TI;
  return '';
}

return saida.map((j, i) => {
  const ordem = i + 1;
  const destinoTeste = usarAlias
    ? tLocal + '+cecape-' + String(ordem).padStart(pad, '0') + '@' + tDominio
    : emailTeste;
  return {
    json: {
      ...j,
      ORDEM: ordem,
      TOTAL_FILA: total,
      DIVERGENCIAS_NOME: divergencias,
      EMAIL_REAL: emailReal(j),
      EMAIL_TESTE_DESTINO: destinoTeste,
      TESTE_SEQ: String(ordem).padStart(pad, '0') + '/' + total
    }
  };
});

