// =========================================================
// RESUMO FINAL — conta o que o Gmail REALMENTE respondeu em cada envio.
// ---------------------------------------------------------
// Antes, o resumo contava os itens da fila (o que DEVERIA ser enviado).
// Agora percorre todas as execuções dos nós Gmail dentro do loop
// ($('nó').all(0, runIndex)) e classifica cada envio:
//   ENVIADO       -> Gmail devolveu id/labelIds (mensagem aceita e enviada)
//   ERRO          -> Gmail devolveu erro (o nó está com "continue on fail")
//   SEM_RESPOSTA  -> nó rodou mas não devolveu nem id nem erro
//   NAO_EXECUTADO -> item estava na fila, mas o nó Gmail não rodou para ele
// O i-ésimo item de cada tipo na fila corresponde à i-ésima execução do
// nó Gmail daquele tipo (o loop processa a fila em ordem, um item por vez).
// =========================================================

let cfg = {};
try { cfg = $('Config - Variáveis').first().json || {}; } catch (e) { cfg = {}; }

let fila = [];
try {
  fila = $('Code - Regra Nomes Diferentes').all().map(i => i.json);
} catch (e) {
  try { fila = $('Code - Montar Fila de Envios').all().map(i => i.json); } catch (e2) { fila = []; }
}
fila = fila.filter(f => f && ['ALUNO', 'FORMADOR', 'DIVERGENCIA'].includes(f.TIPO_ENVIO));

function execucoesDoNo(nome) {
  const runs = [];
  for (let r = 0; r < 5000; r++) {
    let its;
    try { its = $(nome).all(0, r); } catch (e) { break; }
    if (!Array.isArray(its) || !its.length) break;
    runs.push(its.map(i => (i && i.json) || {}));
  }
  return runs;
}

function statusDaExecucao(run) {
  const j = (run && run[0]) || {};
  if (j.error) {
    const det = typeof j.error === 'string' ? j.error : (j.error.message || j.error.description || JSON.stringify(j.error));
    return { status: 'ERRO', detalhe: String(det).slice(0, 300) };
  }
  if (j.id || (Array.isArray(j.labelIds) && j.labelIds.includes('SENT'))) {
    return { status: 'ENVIADO', detalhe: String(j.id || '') };
  }
  return { status: 'SEM_RESPOSTA', detalhe: '' };
}

const NOS = {
  ALUNO: 'Gmail - Enviar Aluno',
  FORMADOR: 'Gmail - Enviar Formador',
  DIVERGENCIA: 'Gmail - Enviar TI (Divergência)'
};

const execucoes = {};
const ponteiro = {};
for (const tipo of Object.keys(NOS)) {
  execucoes[tipo] = execucoesDoNo(NOS[tipo]);
  ponteiro[tipo] = 0;
}

function escapeHtml(s = '') {
  return String(s ?? '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

const relatorio = [];
for (const f of fila) {
  const tipo = f.TIPO_ENVIO;
  const idx = ponteiro[tipo]++;
  const run = execucoes[tipo][idx];
  const st = run ? statusDaExecucao(run) : { status: 'NAO_EXECUTADO', detalhe: '' };

  const destinatarioReal = f.EMAIL_REAL
    || (tipo === 'ALUNO' ? f.EMAIL_ALUNO : tipo === 'FORMADOR' ? f.PROFESSOR_EMAIL : f.EMAIL_TI)
    || '';
  const destinatarioEfetivo = cfg.MODO_TESTE ? (f.EMAIL_TESTE_DESTINO || cfg.EMAIL_TESTE || '') : destinatarioReal;

  relatorio.push({
    ordem: f.ORDEM,
    tipo,
    curso: f['TÍTULO'] || f.curso_nome || '',
    arquivo: f.spreadsheetName || '',
    data: f.DATA || '',
    nome: tipo === 'ALUNO' ? (f.NOME || '') : tipo === 'FORMADOR' ? (f.PROFESSOR_NOME || '') : 'TI (divergência de nome)',
    destinatario_real: destinatarioReal,
    destinatario_efetivo: destinatarioEfetivo,
    status: st.status,
    detalhe: st.detalhe
  });
}

const porTipo = (tipo, status) => relatorio.filter(r => r.tipo === tipo && (!status || r.status === status)).length;

const resumoTipos = {};
for (const tipo of Object.keys(NOS)) {
  resumoTipos[tipo] = {
    na_fila: porTipo(tipo),
    enviados: porTipo(tipo, 'ENVIADO'),
    erros: porTipo(tipo, 'ERRO'),
    sem_resposta: porTipo(tipo, 'SEM_RESPOSTA'),
    nao_executados: porTipo(tipo, 'NAO_EXECUTADO'),
    execucoes_gmail: execucoes[tipo].length
  };
}

const erros = relatorio.filter(r => r.status !== 'ENVIADO');
const cursos = [...new Set(fila.filter(f => f.TIPO_ENVIO !== 'DIVERGENCIA').map(f => f.spreadsheetName))];
const divergencias = fila.filter(f => f.TIPO_ENVIO === 'DIVERGENCIA');

let status = 'SEM_ENVIOS';
if (relatorio.length) {
  status = erros.length ? (erros.length === relatorio.length ? 'FALHOU' : 'CONCLUIDO_COM_ERROS') : 'CONCLUIDO';
}

// ----- relatório em HTML (usado pelo e-mail de relatório do modo teste) -----
const cor = s => s === 'ENVIADO' ? '#2e7d32' : s === 'ERRO' ? '#c62828' : '#ef6c00';
const linhasHtml = relatorio.map(r =>
  '<tr>' +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:center;">${r.ordem}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${escapeHtml(r.tipo)}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${escapeHtml(r.curso)}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${escapeHtml(r.nome)}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${escapeHtml(r.destinatario_real)}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${escapeHtml(r.destinatario_efetivo)}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;font-weight:bold;color:${cor(r.status)};">${escapeHtml(r.status)}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;font-size:12px;color:#666;">${escapeHtml(r.status === 'ERRO' ? r.detalhe : '')}</td>` +
  '</tr>'
).join('');

const resumoHtml =
  `<p><strong>Status:</strong> ${escapeHtml(status)} &nbsp;|&nbsp; <strong>Modo teste:</strong> ${cfg.MODO_TESTE ? 'SIM (destino ' + escapeHtml(cfg.EMAIL_TESTE || '') + ')' : 'NÃO'}</p>` +
  `<p><strong>Alunos:</strong> ${resumoTipos.ALUNO.enviados}/${resumoTipos.ALUNO.na_fila} enviados` +
  ` &nbsp;|&nbsp; <strong>Formadores:</strong> ${resumoTipos.FORMADOR.enviados}/${resumoTipos.FORMADOR.na_fila} enviados` +
  ` &nbsp;|&nbsp; <strong>Avisos à TI (divergência):</strong> ${resumoTipos.DIVERGENCIA.enviados}/${resumoTipos.DIVERGENCIA.na_fila} enviados</p>` +
  (erros.length ? `<p style="color:#c62828;"><strong>${erros.length} envio(s) NÃO confirmados pelo Gmail.</strong></p>` : '<p style="color:#2e7d32;"><strong>Todos os envios foram confirmados pelo Gmail.</strong></p>');

const tabelaHtml =
  '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
  '<thead><tr style="background:#00accf;color:#fff;">' +
  '<th style="padding:6px 8px;">#</th><th style="padding:6px 8px;">Tipo</th><th style="padding:6px 8px;">Curso</th><th style="padding:6px 8px;">Nome</th>' +
  '<th style="padding:6px 8px;">Destinatário real</th><th style="padding:6px 8px;">Enviado para</th><th style="padding:6px 8px;">Gmail</th><th style="padding:6px 8px;">Erro</th>' +
  '</tr></thead><tbody>' + linhasHtml + '</tbody></table>';


// ----- diários que não puderam ser lidos (erro na API do Sheets) -----
let diariosComErro = [];
try {
  const nomes = $('Code - Preparar Diários').all().map(i => (i.json || {}).spreadsheetName || '');
  const leituras = $('HTTP - Ler Diário (L2 + ID + Alunos)').all().map(i => i.json || {});
  leituras.forEach((r, i) => {
    if (r && r.error) {
      const det = typeof r.error === 'string' ? r.error : (r.error.message || r.error.description || JSON.stringify(r.error));
      diariosComErro.push({ arquivo: nomes[i] || ('diário #' + (i + 1)), erro: String(det).slice(0, 300) });
    }
  });
} catch (e) {
  diariosComErro = [];
}
const diariosErroHtml = diariosComErro.length
  ? '<div style="margin:0 0 16px 0;padding:12px;background:#fdecea;border:1px solid #f5c2c0;border-left:5px solid #c62828;border-radius:8px;color:#7f1d1d;font-size:13px;">' +
    `<strong>⚠️ ${diariosComErro.length} diário(s) não puderam ser lidos na API do Sheets</strong> (podem ter curso na data-alvo sem aviso enviado):<ul style="margin:6px 0 0 0;">` +
    diariosComErro.map(d => `<li>${escapeHtml(d.arquivo)} — <span style="color:#555;">${escapeHtml(d.erro)}</span></li>`).join('') + '</ul></div>'
  : '';

// ----- resumo por curso (para o relatório da TI) -----
const porCursoMap = new Map();
const ordemCursosResumo = [];
for (const f of fila) {
  const k = String(f.spreadsheetId || f.spreadsheetName || '');
  if (!porCursoMap.has(k)) { porCursoMap.set(k, []); ordemCursosResumo.push(k); }
  porCursoMap.get(k).push(f);
}
const statusPorOrdem = new Map(relatorio.map(r => [r.ordem, r.status]));
const cursosResumo = ordemCursosResumo.map(k => {
  const its = porCursoMap.get(k);
  const b = its[0];
  const alunosIts = its.filter(i => i.TIPO_ENVIO === 'ALUNO');
  const formIts = its.filter(i => i.TIPO_ENVIO === 'FORMADOR');
  const divIt = its.find(i => i.TIPO_ENVIO === 'DIVERGENCIA');
  const cont = arr => arr.filter(i => statusPorOrdem.get(i.ORDEM) === 'ENVIADO').length;
  return {
    titulo: b['TÍTULO'] || b.curso_nome || '',
    arquivo: b.spreadsheetName || '',
    data: b.DATA || '',
    horario: b.HORARIO_TEXTO || [b.INICIO, b.TERMINO].filter(Boolean).join(' - '),
    local: b['ESPAÇO'] || '',
    formadores: b.FORMADORES || '',
    fonte_horario: b.FONTE_HORARIO || '',
    fonte_local: b.FONTE_LOCAL || '',
    fonte_data: b.FONTE_DATA || '',
    alunos_na_fila: divIt ? Number(divIt.ALUNOS_TOTAL || 0) : alunosIts.length,
    alunos_linhas_lidas: Number(b.ALUNOS_LINHAS_LIDAS || 0),
    erro_leitura_diario: b.ERRO_LEITURA_DIARIO || '',
    alunos_enviados: cont(alunosIts),
    formadores_na_fila: formIts.length,
    formadores_enviados: cont(formIts),
    divergencia: !!divIt,
    nome_planilha: divIt ? (divIt.NOME_PLANILHA || '') : (b.NOME_PLANILHA || ''),
    aviso_ti: divIt ? (statusPorOrdem.get(divIt.ORDEM) || '') : ''
  };
});

const fonteLabel = f => f === 'DIARIO' ? 'diário (aba ID)' : f === 'AGENDA' ? 'agenda' : (f || '');
const linhasCursosHtml = cursosResumo.map(c =>
  '<tr>' +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${escapeHtml(c.titulo)}<br><span style="font-size:11px;color:#888;">${escapeHtml(c.arquivo)}</span></td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;white-space:nowrap;">${escapeHtml(c.data)}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${escapeHtml(c.horario)}<br><span style="font-size:11px;color:#888;">${escapeHtml(fonteLabel(c.fonte_horario))}</span></td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${escapeHtml(c.local)}<br><span style="font-size:11px;color:#888;">${escapeHtml(fonteLabel(c.fonte_local))}</span></td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${escapeHtml(c.formadores)}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:center;">${c.divergencia ? '<span style="color:#c62828;font-weight:bold;">0</span> de ' + c.alunos_na_fila : c.alunos_enviados + ' de ' + c.alunos_na_fila}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:center;">${c.divergencia ? '<span style="color:#c62828;font-weight:bold;">0</span> de 0' : c.formadores_enviados + ' de ' + c.formadores_na_fila}</td>` +
  `<td style="padding:6px 8px;border-bottom:1px solid #eee;">${c.erro_leitura_diario ? '<span style="color:#c62828;font-weight:bold;">ERRO DE LEITURA DO DIÁRIO</span><br><span style="font-size:11px;">' + escapeHtml(c.erro_leitura_diario) + '</span><br>' : ''}${(!c.divergencia && c.alunos_na_fila === 0) ? '<span style="color:#ef6c00;font-weight:bold;">SEM ALUNOS COM E-MAIL</span><br>' : ''}${c.divergencia ? '<span style="color:#c62828;font-weight:bold;">DIVERGÊNCIA DE NOME</span><br><span style="font-size:11px;">planilha: ' + escapeHtml(c.nome_planilha || '(não encontrado)') + '<br>aviso à TI: ' + escapeHtml(c.aviso_ti) + '</span>' : '<span style="color:#2e7d32;font-weight:bold;">OK</span>'}</td>` +
  '</tr>'
).join('');

const tabelaCursosHtml =
  '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
  '<thead><tr style="background:#00accf;color:#fff;">' +
  '<th style="padding:6px 8px;text-align:left;">Curso</th><th style="padding:6px 8px;">Data</th><th style="padding:6px 8px;">Horário</th><th style="padding:6px 8px;">Local</th>' +
  '<th style="padding:6px 8px;">Formador(es)</th><th style="padding:6px 8px;">Alunos avisados</th><th style="padding:6px 8px;">Formadores avisados</th><th style="padding:6px 8px;">Situação</th>' +
  '</tr></thead><tbody>' + linhasCursosHtml + '</tbody></table>';

const errosTiHtml = erros.length
  ? '<p style="color:#c62828;margin-top:16px;"><strong>Envios não confirmados pelo Gmail (' + erros.length + '):</strong></p><ul style="font-size:13px;">' +
    erros.map(e => `<li>#${e.ordem} ${escapeHtml(e.tipo)} • ${escapeHtml(e.curso)} • ${escapeHtml(e.nome)} &lt;${escapeHtml(e.destinatario_real)}&gt; — <strong>${escapeHtml(e.status)}</strong>${e.detalhe ? ': ' + escapeHtml(e.detalhe) : ''}</li>`).join('') + '</ul>'
  : '';

const relatorioTiHtml = resumoHtml + diariosErroHtml + tabelaCursosHtml + errosTiHtml;

return [{
  json: {
    status,
    modo_teste: !!cfg.MODO_TESTE,
    email_teste: cfg.MODO_TESTE ? (cfg.EMAIL_TESTE || '') : '',
    data_alvo: (fila[0] && fila[0].DATA) || '',
    cursos_processados: cursos.length,
    cursos,
    emails_alunos: resumoTipos.ALUNO.enviados,
    emails_alunos_na_fila: resumoTipos.ALUNO.na_fila,
    emails_formadores: resumoTipos.FORMADOR.enviados,
    emails_formadores_na_fila: resumoTipos.FORMADOR.na_fila,
    divergencias_nome: divergencias.length,
    avisos_ti_enviados: resumoTipos.DIVERGENCIA.enviados,
    cursos_com_divergencia: divergencias.map(d => ({ arquivo: d.spreadsheetName, nome_planilha: d.NOME_PLANILHA || '', alunos_nao_avisados: d.ALUNOS_TOTAL })),
    total_fila: relatorio.length,
    total_enviados: relatorio.length - erros.length,
    total_nao_confirmados: erros.length,
    por_tipo: resumoTipos,
    erros,
    relatorio,
    relatorio_html: resumoHtml + tabelaHtml,
    cursos_resumo: cursosResumo,
    diarios_com_erro: diariosComErro,
    relatorio_ti_html: relatorioTiHtml,
    email_ti: cfg.EMAIL_TI || 'ti.cecape@scseduca.com.br',
    mensagem: relatorio.length
      ? `Fila processada: ${relatorio.length - erros.length} de ${relatorio.length} envios confirmados pelo Gmail` +
        (erros.length ? `; ${erros.length} não confirmado(s) — veja "erros".` : '.') +
        (divergencias.length ? ` ${divergencias.length} curso(s) com divergência de nome: aviso enviado à TI.` : '')
      : 'Nenhum e-mail para enviar na(s) data(s)-alvo.'
  }
}];
